/**
 * 参赛者参赛状态：
 * ACTIVE-有效，可被冲线证据引用并参与排名；
 * WITHDRAWN-已退赛，不参与排名，裁决证据时作为“候选人失效”处理（422）。
 */
public enum RunnerStatus {
    ACTIVE,
    WITHDRAWN
}

package com.example.starter.race.domain;

/**
 * 冲线证据状态：
 * PENDING-已登记、尚未裁决，可撤回；
