    for (int groupIndex = index; groupIndex < groupEnd; groupIndex++) {
        if (!evidenceOrderByBib.containsKey(ranked.get(groupIndex).bib)) {
            fullyAdjudicated = false;
            break;
        }
    }
    if (fullyAdjudicated) {
        for (int groupIndex = index; groupIndex < groupEnd; groupIndex++) {
            ranked.get(groupIndex).rank = groupIndex + 1;
        }
    } else {
        int rank = index + 1;
        for (int groupIndex = index; groupIndex < groupEnd; groupIndex++) {
            ranked.get(groupIndex).rank = rank;
        }
    }
    index = groupEnd;
}

