        mockMvc.perform(post("/api/races/race-api/penalties")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"penaltyId":"pen-1","bib":"b","type":"ADD_TIME","amountMs":100,
                                 "expectedVersion":4,"requestId":"req-pen"}
                                """))

